/* 학습 해설
 * MADV_FREE Resident Folio: Dirty를 지우고 Lazyfree 후보로 만들기
 * 아직 RAM에 있는 불필요한 데이터를 바로 모두 해제하면 이후 다시 사용할 때 비용이 생길 수 있습니다. lazyfree는 회수 가능한 후보로 표시하는 방식이며,더러운 데이터의 보존 요구와 swap cache 상태도 함께 정리해야 합니다.
 * present PTE에서는 normal folio가 아니거나 zone device이면 건너뜁니다. 큰 folio는 배치와 필요 시 분할을 사용하며 완전히 포함된 배치의 young·dirty를 합칩니다. swapcache 또는 dirty folio는 trylock하고 mapcount가 페이지 수와 다르면 건너뜁니다. swapcache 해제 실패도 건너뜁니다. 성공하면 folio dirty를 지우고 PTE의 young·dirty를 지운 뒤 TLB 제거를 기록하고 folio_mark_lazyfree를 호출합니다.
 * 4페이지 folio의 PTE 중 하나만 dirty여도 any_dirty로 묶음에 반영해야 합니다. 첫 PTE만 깨끗하다는 이유로 전체 배치가 깨끗하다고 볼 수 없기 때문입니다. folio_mark_lazyfree 호출은 그 자리에서 사용자 페이지를 memset(0)하는 코드가 아닙니다. lazyfree 이후 실제 회수·재사용 정책은 별도 reclaim 구현과 이어집니다.
 */
static int madvise_free_pte_range(pmd_t *pmd, unsigned long addr,
				unsigned long end, struct mm_walk *walk)

{
	const cydp_t cydp_flags = CYDP_CLEAR_YOUNG | CYDP_CLEAR_DIRTY;
	struct mmu_gather *tlb = walk->private;
	struct mm_struct *mm = tlb->mm;
	struct vm_area_struct *vma = walk->vma;
	spinlock_t *ptl;
	pte_t *start_pte, *pte, ptent;
	struct folio *folio;
	int nr_swap = 0;
	unsigned long next;
	int nr, max_nr;

	next = pmd_addr_end(addr, end);
	if (pmd_trans_huge(*pmd))
		if (madvise_free_huge_pmd(tlb, vma, pmd, addr, next))
			return 0;

	tlb_change_page_size(tlb, PAGE_SIZE);
	start_pte = pte = pte_offset_map_lock(mm, pmd, addr, &ptl);
	if (!start_pte)
		return 0;
	flush_tlb_batched_pending(mm);
	arch_enter_lazy_mmu_mode();

/* 학습 해설
 * WILLNEED Swap-in: PTE 잠금과 Shmem XArray 순회를 I/O 앞에서 놓기
 * swap에 있는 데이터를 미리 읽으려면 어떤 swap entry를 읽을지 찾는 보호와 실제 읽기 작업을 분리해야 합니다. 페이지 테이블 spinlock이나 RCU 읽기 구간을 잡은 채 긴 작업을 수행하면 다른 작업의 진행과 객체 수명 관리에 문제가 생깁니다.
 * swapin_walk_pmd_entry는 PTE를 map/lock해 일반 swap entry를 찾습니다. present나 특수 non-swap entry는 건너뜁니다. 읽을 entry가 있으면 PTE 잠금을 놓고 read_swap_cache_async를 호출해 얻은 folio 참조를 put합니다. 다음 주소에서는 PTE를 다시 map/lock합니다. 끝에서 남은 잠금을 정리하고 swap_read_unplug,cond_resched 후 0입니다.
 * 세 PTE가 [present,일반 swap,특수 entry]라면 일반 swap 항목에만 읽기 helper를 호출합니다. swap처럼 표현된 모든 entry가 디스크 위치인 것은 아닙니다. 읽기 helper가 NULL을 반환해도 이 callback에는 그것을 음수 오류로 바꾸는 분기가 없으므로 0을 모든 swap-in 성공 보장으로 해석하지 않습니다.
 */
static int swapin_walk_pmd_entry(pmd_t *pmd, unsigned long start,
		unsigned long end, struct mm_walk *walk)
{
	struct vm_area_struct *vma = walk->private;
	struct swap_iocb *splug = NULL;
	pte_t *ptep = NULL;
	spinlock_t *ptl;
	unsigned long addr;

	for (addr = start; addr < end; addr += PAGE_SIZE) {
		pte_t pte;
		swp_entry_t entry;
		struct folio *folio;

		if (!ptep++) {
			ptep = pte_offset_map_lock(vma->vm_mm, pmd, addr, &ptl);
			if (!ptep)
				break;
		}

		pte = ptep_get(ptep);
		if (!is_swap_pte(pte))
			continue;
		entry = pte_to_swp_entry(pte);
		if (unlikely(non_swap_entry(entry)))
			continue;

/* 학습 해설
 * 익명 VMA 이름: 같은 문자열 재사용과 참조 포화 시 복제
 * 익명 메모리 영역에 이름을 붙이면 여러 영역의 용도를 구분할 수 있습니다. 이름을 VMA마다 무조건 복사하면 공간이 낭비되고,무조건 공유하면 참조 수의 한계와 수명 처리를 놓칠 수 있어 별도 이름 객체를 관리합니다.
 * alloc은 문자열 길이에 NUL 1바이트를 더해 flexible array를 포함한 구조체를 할당하고 kref를 초기화한 뒤 복사합니다. replace는 새 이름이 NULL이면 기존 참조를 놓고 이름을 지웁니다. 이름이 같으면 그대로 두고,다르면 reuse로 새 참조를 얻은 뒤 기존 참조를 놓습니다. mm_inline.h의 equality는 포인터가 같거나 두 비NULL 문자열이 strcmp로 같으면 true입니다.
 * 서로 다른 객체가 모두 cache라는 문자열을 담아도 equality는 true일 수 있습니다. reuse는 refcount가 REFCOUNT_MAX보다 작으면 참조를 늘려 같은 객체를 반환하고,한계 이상이면 이름 문자열로 새 객체를 할당합니다. 새 할당 실패는 NULL이 될 수 있으며 replace는 이를 별도 오류 검사하지 않고 저장한 뒤 0을 반환합니다. 이름 보존이 항상 성공한다고 과장하지 않습니다.
 */
static int replace_anon_vma_name(struct vm_area_struct *vma,
				 struct anon_vma_name *anon_name)
{
	struct anon_vma_name *orig_name = anon_vma_name(vma);

	if (!anon_name) {
		vma->anon_name = NULL;
		anon_vma_name_put(orig_name);
		return 0;
	}

	if (anon_vma_name_eq(orig_name, anon_name))
		return 0;

	vma->anon_name = anon_vma_name_reuse(anon_name);
	anon_vma_name_put(orig_name);

	return 0;
}
#else /* CONFIG_ANON_VMA_NAME */
static int replace_anon_vma_name(struct vm_area_struct *vma,
				 struct anon_vma_name *anon_name)
{
	if (anon_name)
		return -EINVAL;

/* 학습 해설
 * Madvise 메모리 오류 주입: 거대 페이지 크기를 미리 저장하는 이유
 * 메모리 오류 처리 경로를 시험하려면 실제 하드웨어 고장 없이 오류를 주입할 수 있어야 합니다. 그러나 페이지 격리·이동이 대상 객체의 형태를 바꿀 수 있으므로 다음 주소를 계산할 크기는 변화 전에 확보해야 합니다.
 * CONFIG_MEMORY_FAILURE에서 helper는 CAP_SYS_ADMIN이 없으면 EPERM입니다. 주소마다 get_user_pages_fast로 한 페이지를 얻고 결과가 1이 아니면 그 값을 그대로 반환합니다. PFN과 compound_head의 page_size를 먼저 구합니다. SOFT_OFFLINE은 soft_offline_page,HWPOISON은 memory_failure를 호출합니다. 뒤의 memory_failure 경로에서는 EOPNOTSUPP를 0으로 바꾸며 그 밖의 오류는 반환합니다.
 * 현재 compound page가 2MiB이고 soft offline 과정에서 작은 페이지들로 분해되면 처리 뒤 크기를 읽어 다음 위치를 계산할 때 원래 범위를 잘못 재방문할 수 있습니다. 그래서 원래 크기를 저장하고 start+=size로 전진합니다. 크기 변수는 get_user_pages_fast 요청 개수 1과 같은 단위가 아니며 compound page 전체 크기입니다.
 */
static int madvise_inject_error(int behavior,
		unsigned long start, unsigned long end)
{
	unsigned long size;

	if (!capable(CAP_SYS_ADMIN))
		return -EPERM;


	for (; start < end; start += size) {
		unsigned long pfn;
		struct page *page;
		int ret;

		ret = get_user_pages_fast(start, 1, 0, &page);
		if (ret != 1)
			return ret;
		pfn = page_to_pfn(page);

		/*
		 * When soft offlining hugepages, after migrating the page
		 * we dissolve it, therefore in the second loop "page" will
		 * no longer be a compound page.
		 */
		size = page_size(compound_head(page));

/* 학습 해설
 * ICMP CPU별 송신 소켓: 재진입에서 기다리지 않는 Trylock
 * ICMP 오류 패킷을 보내는 도중 출력 경로가 다시 오류를 보고할 수 있습니다. 같은 송신 소켓 잠금을 이미 가진 실행 흐름이 다시 기다리면 스스로 풀 수 없는 잠금을 기다리는 상황이 생길 수 있어 재진입 경로를 조심해야 합니다.
 * ipv4_icmp_sk는 CPU별 소켓 포인터입니다. icmp_xmit_lock은 BH가 비활성인 상태에서 this_cpu_read로 소켓을 얻고 sk_lock.slock에 spin_trylock을 시도합니다. 실패하면 NULL을 반환하고 성공하면 소켓의 network namespace를 요청 net으로 설정합니다. unlock은 init_net으로 되돌린 뒤 spin_unlock합니다.
 * 첫 ICMP 송신이 소켓 잠금을 보유한 상태에서 dst_link_failure가 다시 ICMP를 유발하면 두 번째 시도는 기다리는 대신 NULL이 될 수 있습니다. 호출자 icmp_reply는 이 경우 BH 복구 경로로 갑니다. CPU별 객체는 모든 경쟁을 자동 제거한다는 뜻이 아니며 같은 CPU의 재진입도 고려해야 합니다.
 */
static inline struct sock *icmp_xmit_lock(struct net *net)
{
	struct sock *sk;

	sk = this_cpu_read(ipv4_icmp_sk);

	if (unlikely(!spin_trylock(&sk->sk_lock.slock))) {
		/* This can happen if the output path signals a
		 * dst_link_failure() for an outgoing ICMP packet.
		 */
		return NULL;
	}
	sock_net_set(sk, net);
	return sk;
}

static inline void icmp_xmit_unlock(struct sock *sk)
{
	sock_net_set(sk, &init_net);
	spin_unlock(&sk->sk_lock.slock);
}

/**
 * icmp_global_allow - Are we allowed to send one more ICMP message ?
 * @net: network namespace
 *
 * Uses a token bucket to limit our ICMP messages to ~sysctl_icmp_msgs_per_sec.
 * Returns false if we reached the limit and can not send another packet.
 * Works in tandem with icmp_global_consume().
 */

/* 학습 해설
 * ICMP Token Bucket 보충: 시간 경과를 정수 Credit으로 바꾸기
 * 오류 응답이 너무 많으면 오류 처리 자체가 CPU와 네트워크를 소모합니다. 시간에 따라 발급되는 전송 여유량을 관리하면 평균 전송률을 제한하면서 짧은 집중 요청은 일정 한도까지 허용할 수 있습니다.
 * icmp_global_allow는 해당 net의 credit이 양수이면 바로 true입니다. 그렇지 않으면 jiffies 차이를 최대 HZ로 제한하고 HZ/50보다 짧으면 false입니다. incr=msgs_per_sec*delta/HZ가 0이어도 false입니다. stamp의 cmpxchg 승자만 보충을 시도하고 credit은 atomic_try_cmpxchg 반복으로 min(old+incr,msgs_burst)가 되도록 갱신합니다.
 * 학습용 HZ=1000,초당 100개,100 tick 경과면 incr=10입니다. 기존 credit=-2,burst=20이면 새 값은 8입니다. 기존 0에서 오래 쉬어 5000 tick이 지나도 delta는 1000으로 제한되고 burst 상한도 적용됩니다. 쉬었던 모든 시간을 무제한 전송권으로 저축하지 않는 구조입니다.
 */
bool icmp_global_allow(struct net *net)
{
	u32 delta, now, oldstamp;
	int incr, new, old;

	/* Note: many cpus could find this condition true.
	 * Then later icmp_global_consume() could consume more credits,
	 * this is an acceptable race.
	 */
	if (atomic_read(&net->ipv4.icmp_global_credit) > 0)
		return true;

	now = jiffies;
	oldstamp = READ_ONCE(net->ipv4.icmp_global_stamp);
	delta = min_t(u32, now - oldstamp, HZ);
	if (delta < HZ / 50)
		return false;

	incr = READ_ONCE(net->ipv4.sysctl_icmp_msgs_per_sec) * delta / HZ;
	if (!incr)
		return false;

	if (cmpxchg(&net->ipv4.icmp_global_stamp, oldstamp, now) == oldstamp) {
		old = atomic_read(&net->ipv4.icmp_global_credit);
		do {
			new = min(old + incr, READ_ONCE(net->ipv4.sysctl_icmp_msgs_burst));

/* 학습 해설
 * ICMP Credit 소비 경쟁: 왜 음수도 허용되는가
 * 여러 CPU가 빠르게 오류를 보내는 경로에서 허용 검사와 실제 소비를 하나의 전역 직렬 구간으로 묶으면 비용이 커질 수 있습니다. 이 구현은 허용과 소비를 나누며 정확한 개수 예약 대신 근사적인 제한을 사용합니다.
 * icmp_global_allow가 양수 credit을 확인해도 그 자리에서 차감하지 않습니다. 이후 icmp_global_consume는 get_random_u32_below(3)으로 0·1·2 중 하나를 얻고 0이 아닐 때 atomic_sub합니다. 원문은 여러 CPU가 같은 양수 상태를 보고 통과하며 뒤 소비로 credit이 음수가 될 수 있음을 허용하는 경쟁이라고 명시합니다.
 * credit=1을 CPU A와 B가 모두 확인해 통과하고 각각 2를 소비하면 최종 값은 -3입니다. 두 번 전송했으므로 반드시 -1이라고 계산할 수 없습니다. 다음 허용 검사는 양수 빠른 경로를 통과하지 못하고 시간 보충 조건으로 갑니다. 이것은 unsigned underflow를 우연히 이용하는 코드가 아니라 signed credit의 음수 가능성을 고려한 흐름입니다.
 */
void icmp_global_consume(struct net *net)
{
	int credits = get_random_u32_below(3);

	/* Note: this might make icmp_global.credit negative. */
	if (credits)
		atomic_sub(credits, &net->ipv4.icmp_global_credit);
}
EXPORT_SYMBOL(icmp_global_consume);

static bool icmpv4_mask_allow(struct net *net, int type, int code)
{
	if (type > NR_ICMP_TYPES)
		return true;

	/* Don't limit PMTU discovery. */
	if (type == ICMP_DEST_UNREACH && code == ICMP_FRAG_NEEDED)
		return true;

	/* Limit if icmp type is enabled in ratemask. */
	if (!((1 << type) & READ_ONCE(net->ipv4.sysctl_icmp_ratemask)))
		return true;

	return false;
}

/* 학습 해설
 * ICMP 제한 예외: PMTU 메시지와 목적지별 Token을 구분하기
 * 모든 ICMP를 같은 방식으로 제한하면 통신에 필요한 제어 메시지까지 지연될 수 있습니다. 전체 namespace 제한과 목적지별 제한도 다른 문제를 다루므로 어떤 메시지를 어느 단계에서 제외하는지 구분해야 합니다.
 * icmpv4_mask_allow는 범위 밖 type,DEST_UNREACH의 FRAG_NEEDED,ratemask에 비트가 없는 type을 허용합니다. 해당 예외는 apply_ratelimit을 켜지 않습니다. 제한 대상은 전역 허용을 통과할 때 apply_ratelimit=true입니다. 목적지 제한 함수는 false이면 바로 true이고,출력 loopback이면 peer 검사만 건너뜁니다. 그 외에는 목적지 주소와 L3 master index로 peer를 얻어 inet_peer_xrlim_allow를 호출합니다.
 * apply_ratelimit=false이면 전역 consume도 생략됩니다. 반대로 true인 상태에서 출력 장치가 loopback이면 peer 검사는 건너뛰지만 out 경로에서 전역 credit은 소비합니다. 목적지 제한 실패는 RATELIMITHOST를 증가시키고 소비하지 않습니다. 전역 제한 실패는 별도 RATELIMITGLOBAL 통계를 증가시킵니다.
 */
static bool icmpv4_xrlim_allow(struct net *net, struct rtable *rt,
			       struct flowi4 *fl4, int type, int code,
			       bool apply_ratelimit)
{
	struct dst_entry *dst = &rt->dst;
	struct inet_peer *peer;
	bool rc = true;
	int vif;

	if (!apply_ratelimit)
		return true;

	/* No rate limit on loopback */
	if (dst->dev && (dst->dev->flags&IFF_LOOPBACK))
		goto out;

	vif = l3mdev_master_ifindex(dst->dev);
	peer = inet_getpeer_v4(net->ipv4.peers, fl4->daddr, vif, 1);
	rc = inet_peer_xrlim_allow(peer,
				   READ_ONCE(net->ipv4.sysctl_icmp_ratelimit));
	if (peer)
		inet_putpeer(peer);
out:
	if (!rc)
		__ICMP_INC_STATS(net, ICMP_MIB_RATELIMITHOST);
