/* 학습 해설
 * ICMP 응답 조립: 여러 SKB의 Checksum을 합쳐 헤더에 넣기
 * 응답 데이터가 여러 SKB로 나뉘어 있으면 첫 버퍼만 검사해서 전체 메시지의 checksum을 만들 수 없습니다. 각 조각을 복사하면서 얻은 부분 합과 ICMP 헤더의 합을 결합해야 합니다.
 * icmp_glue_bits는 원본 skb의 offset+요청 offset에서 데이터를 복사하며 checksum을 계산하고 csum_block_add로 odd 위치를 반영해 출력 skb의 합에 더합니다. 오류 유형이면 nf_ct_attach도 수행합니다. push_reply는 ip_append_data에 전체 데이터+헤더 길이,헤더 길이,MSG_DONTWAIT를 전달합니다. 음수면 OUTERRORS를 늘리고 pending frames를 비웁니다.
 * 조립 성공 후 큐가 비어 있지 않으면 첫 skb의 ICMP 헤더에 준비한 헤더를 복사하며 합을 얻고,write queue의 모든 skb->csum을 csum_add합니다. 마지막 csum_fold 결과를 헤더 checksum에 넣고 CHECKSUM_NONE으로 설정한 뒤 ip_push_pending_frames를 호출합니다. 두 SKB에 데이터가 나뉘면 두 부분 합을 모두 더하며 단순히 첫 skb의 checksum만 복사하지 않습니다.
 */
static void icmp_push_reply(struct sock *sk,
			    struct icmp_bxm *icmp_param,
			    struct flowi4 *fl4,
			    struct ipcm_cookie *ipc, struct rtable **rt)
{
	struct sk_buff *skb;

	if (ip_append_data(sk, fl4, icmp_glue_bits, icmp_param,
			   icmp_param->data_len+icmp_param->head_len,
			   icmp_param->head_len,
			   ipc, rt, MSG_DONTWAIT) < 0) {
		__ICMP_INC_STATS(sock_net(sk), ICMP_MIB_OUTERRORS);
		ip_flush_pending_frames(sk);
	} else if ((skb = skb_peek(&sk->sk_write_queue)) != NULL) {
		struct icmphdr *icmph = icmp_hdr(skb);
		__wsum csum;
		struct sk_buff *skb1;

		csum = csum_partial_copy_nocheck((void *)&icmp_param->data,
						 (char *)icmph,
						 icmp_param->head_len);
		skb_queue_walk(&sk->sk_write_queue, skb1) {
			csum = csum_add(csum, skb1->csum);
		}
		icmph->checksum = csum_fold(csum);
		skb->ip_summed = CHECKSUM_NONE;

/* 학습 해설
 * ICMP 오류에 다시 오류를 보내지 않기: 반응 폭주를 막는 송신 조건
 * 오류 메시지가 또 오류 메시지를 유발하면 서로 실패를 보고하는 트래픽이 끝없이 이어질 수 있습니다. 브로드캐스트에 여러 장치가 동시에 응답하는 것도 트래픽을 증폭시킬 수 있어 ICMP 오류 송신 전에 대상 패킷을 걸러냅니다.
 * __icmp_send는 route와 namespace를 얻지 못하면 종료합니다. 원본 IP 헤더가 skb 저장 범위 안인지 검사하고 PACKET_HOST가 아니거나 route가 broadcast·multicast이면 종료합니다. IP_OFFSET 비트가 있으면 첫 fragment가 아니므로 종료합니다. 보내려는 type이 오류이고 원본 protocol도 ICMP이면 원본 inner type을 안전하게 읽어,알 수 없는 type 또는 오류 type에 대해서는 응답하지 않습니다.
 * 원본이 ICMP destination unreachable이고 이번에도 오류를 보내려 하면 이 재귀 방지 조건에서 멈춥니다. 반면 echo request 같은 비오류 ICMP에 대해 오류를 보낼 가능성까지 전부 금지하는 조건은 아닙니다. 첫 fragment라도 MF 비트만 있다는 이유로 여기서 거절하지는 않습니다. 검사는 fragment offset 마스크입니다.
 */
void __icmp_send(struct sk_buff *skb_in, int type, int code, __be32 info,
		 const struct ip_options *opt)
{
	struct iphdr *iph;
	int room;
	struct icmp_bxm icmp_param;
	struct rtable *rt = skb_rtable(skb_in);
	bool apply_ratelimit = false;
	struct ipcm_cookie ipc;
	struct flowi4 fl4;
	__be32 saddr;
	u8  tos;
	u32 mark;
	struct net *net;
	struct sock *sk;

	if (!rt)
		goto out;

	if (rt->dst.dev)
		net = dev_net(rt->dst.dev);
	else if (skb_in->dev)
		net = dev_net(skb_in->dev);
	else
		goto out;

/* 학습 해설
 * ICMP 수신 입구: Checksum·Type 검사와 SKB 소유권
 * 네트워크에서 받은 바이트를 곧바로 함수 포인터 테이블의 인덱스로 사용하면 범위를 벗어날 수 있습니다. 검증 실패 통계를 남기고 마지막에 패킷 버퍼를 누가 해제하는지도 정해야 오류 경로에서 중복 해제나 누수가 생기지 않습니다.
 * icmp_rcv는 먼저 XFRM 입력 정책을 검사합니다. 실패하면 sec_path의 ICMP 허용 flag를 확인하고 인용 IP 헤더를 대상으로 reverse 정책을 검사하는 예외 경로가 있습니다. 통과 후 INMSGS를 늘리고 checksum을 검증하며 ICMP 헤더를 pull합니다. type별 통계 뒤 EXT_ECHO와 EXT_ECHOREPLY를 별도 처리하고,나머지는 NR_ICMP_TYPES 범위 검사 후 일반 handler로 보냅니다.
 * 일반 테이블은 19항목인데 EXT_ECHO는 type42입니다. 먼저 별도 처리하므로 42로 19항목 배열을 인덱싱하지 않습니다. checksum 실패는 CSUMERRORS와 INERRORS를 모두 늘리지만 맨 앞 XFRM 정책 거절은 그 통계 갱신보다 먼저 drop합니다. 모든 버림이 같은 통계 변화라고 가정하면 원인 분석이 틀릴 수 있습니다.
 */
int icmp_rcv(struct sk_buff *skb)
{
	enum skb_drop_reason reason = SKB_DROP_REASON_NOT_SPECIFIED;
	struct rtable *rt = skb_rtable(skb);
	struct net *net = dev_net(rt->dst.dev);
	struct icmphdr *icmph;

	if (!xfrm4_policy_check(NULL, XFRM_POLICY_IN, skb)) {
		struct sec_path *sp = skb_sec_path(skb);
		int nh;

		if (!(sp && sp->xvec[sp->len - 1]->props.flags &
				 XFRM_STATE_ICMP)) {
			reason = SKB_DROP_REASON_XFRM_POLICY;
			goto drop;
		}

		if (!pskb_may_pull(skb, sizeof(*icmph) + sizeof(struct iphdr)))
			goto drop;

		nh = skb_network_offset(skb);
		skb_set_network_header(skb, sizeof(*icmph));

		if (!xfrm4_policy_check_reverse(NULL, XFRM_POLICY_IN,
						skb)) {
			reason = SKB_DROP_REASON_XFRM_POLICY;

/* 학습 해설
 * ICMP Unreachable의 Info: MTU·문제 바이트·시간 초과는 다른 값이다
 * ICMP 오류는 원본 패킷의 헤더와 오류별 부가 정보를 전달합니다. 하나의 info 변수라도 오류 종류에 따라 MTU,문제가 있는 바이트 위치,또는 0이 되므로 숫자만 보고 의미를 정할 수 없습니다.
 * icmp_unreach는 최소 IP 헤더를 pull하고 ihl<5이면 IP_INHDR로 거절합니다. FRAG_NEEDED는 ip_no_pmtu_disc가 0이면 16비트 MTU를 host 순서로 info에 넣습니다. 2이면 전달 없이 종료하고,3이면 해당 protocol의 strict tag validation 지원을 확인한 뒤 MTU를 사용합니다. 그 외 값은 로그 경로이며 info의 초기0을 유지합니다. code가 NR_ICMP_UNREACH보다 크면 종료합니다.
 * PARAMETERPROB는 ntohl(gateway)>>24로 상위 바이트를 문제 위치로 얻습니다. 예를 들어 host 변환 후 0x14000000이면 info=20입니다. TIME_EXCEEDED는 통계를 올리지만 fragment reassembly timeout code는 전달 없이 끝냅니다. 같은 info=20도 FRAG_NEEDED 문맥에서는 MTU,PARAMETERPROB 문맥에서는 바이트 위치이므로 type과 함께 해석해야 합니다.
 */
static enum skb_drop_reason icmp_unreach(struct sk_buff *skb)
{
	enum skb_drop_reason reason = SKB_NOT_DROPPED_YET;
	const struct iphdr *iph;
	struct icmphdr *icmph;
	struct net *net;
	u32 info = 0;

	net = dev_net(skb_dst(skb)->dev);

	/*
	 *	Incomplete header ?
	 * 	Only checks for the IP header, there should be an
	 *	additional check for longer headers in upper levels.
	 */

	if (!pskb_may_pull(skb, sizeof(struct iphdr)))
		goto out_err;

	icmph = icmp_hdr(skb);
	iph   = (const struct iphdr *)skb->data;

	if (iph->ihl < 5)  { /* Mangled header, drop. */
		reason = SKB_DROP_REASON_IP_INHDR;
		goto out_err;
	}

/* 학습 해설
 * ICMP 오류 전달: 인용 IP의 Protocol로 원래 통신을 찾기
 * 외부 패킷은 ICMP이지만 오류의 영향을 받는 통신은 원본 TCP·UDP·ICMP일 수 있습니다. 인용된 원본 IP 헤더의 protocol을 읽어 해당 전송 계층에 알려야 원래 소켓이 오류를 해석할 수 있습니다.
 * icmp_socket_deliver는 skb->data의 인용 IP protocol을 얻고 ihl*4+8바이트를 pull할 수 있는지 검사합니다. 부족하면 INERRORS를 올리고 반환합니다. 충분하면 raw_icmp_error에 알리고 inet_protos[protocol]의 err_handler가 있을 때 호출합니다. redirect는 최소 IP 길이와 pull을 검사한 뒤 gateway를 ntohl해 이 전달 helper에 넘깁니다.
 * 인용 IP의 ihl=5이면 IP20바이트에 전송 계층 앞8바이트를 더한 최소28바이트를 확보하려 합니다. 외부 ICMP 헤더의 type과 인용 IP의 protocol은 다른 필드입니다. ICMP 자체 통신의 오류를 받는 icmp_err는 인용 inner type이 ECHOREPLY가 아니면 ping_err로 넘기고,커널 ECHOREPLY에 대한 FRAG_NEEDED와 REDIRECT는 PMTU 갱신·redirect helper로 보냅니다.
 */
static void icmp_socket_deliver(struct sk_buff *skb, u32 info)
{
	const struct iphdr *iph = (const struct iphdr *)skb->data;
	const struct net_protocol *ipprot;
	int protocol = iph->protocol;

	/* Checkin full IP header plus 8 bytes of protocol to
	 * avoid additional coding at protocol handlers.
	 */
	if (!pskb_may_pull(skb, iph->ihl * 4 + 8)) {
		__ICMP_INC_STATS(dev_net(skb->dev), ICMP_MIB_INERRORS);
		return;
	}

	raw_icmp_error(skb, protocol, info);

	ipprot = rcu_dereference(inet_protos[protocol]);
	if (ipprot && ipprot->err_handler)
		ipprot->err_handler(skb, info);
}

static bool icmp_tag_validation(int proto)
{
	bool ok;

	rcu_read_lock();

/* 학습 해설
 * ICMP Echo와 Timestamp: 돌려줄 데이터와 새로 만드는 시간을 구분하기
 * Echo는 요청 데이터를 돌려보내지만 timestamp는 요청의 원래 시각과 응답 측이 측정한 시각을 함께 제공합니다. 같은 reply helper를 사용해도 어떤 바이트를 복사하고 어떤 바이트를 새로 만드는지 다릅니다.
 * icmp_echo는 echo_ignore_all이면 조용히 0 reason을 반환합니다. 그 외에 ICMP 헤더를 복사하고 skb의 남은 payload 전체를 offset0으로 지정합니다. ECHO는 ECHOREPLY로 바꾸고 확장 echo는 build_probe 성공 여부를 확인한 뒤 icmp_reply를 호출합니다. timestamp는 payload가4바이트보다 짧으면 INERRORS와 PKT_TOO_SMALL입니다.
 * timestamp는 요청의 첫4바이트를 times[0]으로 복사하고 inet_current_timestamp 값을 times[1]에,같은 값을 times[2]에 둡니다. 따라서 이 코드의 수신 시각과 송신 시각 필드는 서로 다른 시점에 두 번 측정하지 않습니다. head_len은 ICMP8+시간12=20이고 data_len=0으로 설정해 요청의 추가 payload를 모두 반사하지 않습니다.
 */
static enum skb_drop_reason icmp_echo(struct sk_buff *skb)
{
	struct icmp_bxm icmp_param;
	struct net *net;

	net = dev_net(skb_dst(skb)->dev);
	/* should there be an ICMP stat for ignored echos? */
	if (READ_ONCE(net->ipv4.sysctl_icmp_echo_ignore_all))
		return SKB_NOT_DROPPED_YET;

	icmp_param.data.icmph	   = *icmp_hdr(skb);
	icmp_param.skb		   = skb;
	icmp_param.offset	   = 0;
	icmp_param.data_len	   = skb->len;
	icmp_param.head_len	   = sizeof(struct icmphdr);

	if (icmp_param.data.icmph.type == ICMP_ECHO)
		icmp_param.data.icmph.type = ICMP_ECHOREPLY;
	else if (!icmp_build_probe(skb, &icmp_param.data.icmph))
		return SKB_NOT_DROPPED_YET;

	icmp_reply(&icmp_param, skb);
	return SKB_NOT_DROPPED_YET;
}

/*	Helper for icmp_echo and icmpv6_echo_reply.
 *	Searches for net_device that matches PROBE interface identifier
 *		and builds PROBE reply message in icmphdr.
 *
 *	Returns false if PROBE responses are disabled via sysctl
 */

/* 학습 해설
 * ICMP Probe 식별자 검사: 길이부터 확인하고 이름·인덱스·주소를 읽기
 * 확장 echo는 특정 인터페이스 상태를 묻기 위해 이름이나 인덱스·주소를 전달합니다. 네트워크 입력의 길이를 믿고 문자열 복사나 주소 해석을 하면 버퍼 범위를 벗어날 수 있어 식별자 형식마다 길이 검사가 필요합니다.
 * build_probe는 probe 설정이 꺼졌거나 sequence의 L bit가 없으면 false입니다. 처리할 때 sequence 하위8비트를 지우고 reply type으로 바꿉니다. 확장 헤더와 객체 헤더를 읽고 객체 길이가 헤더보다 크고 로컬 iio 크기 이하인지 검사한 뒤 전체 식별자를 다시 읽습니다. NAME은 ident_len<IFNAMSIZ,INDEX는 정확히 ifindex 크기를 요구합니다.
 * NAME은0으로 채운 IFNAMSIZ 버퍼에 ident_len만 복사하므로 끝에 NUL이 남습니다. ident_len이 IFNAMSIZ와 같으면 이 보장이 없어지므로 거절합니다. INDEX는 ntohl로 바꾸어 dev_get_by_index에 전달합니다. ADDR는 자체 헤더+addrlen 합이 ident_len과 같아야 하고 IPv4는4바이트,IPv6는16바이트 주소 길이를 요구합니다.
 */
bool icmp_build_probe(struct sk_buff *skb, struct icmphdr *icmphdr)
{
	struct icmp_ext_hdr *ext_hdr, _ext_hdr;
	struct icmp_ext_echo_iio *iio, _iio;
	struct net *net = dev_net(skb->dev);
	struct inet6_dev *in6_dev;
	struct in_device *in_dev;
	struct net_device *dev;
	char buff[IFNAMSIZ];
	u16 ident_len;
	u8 status;

	if (!READ_ONCE(net->ipv4.sysctl_icmp_echo_enable_probe))
		return false;

	/* We currently only support probing interfaces on the proxy node
	 * Check to ensure L-bit is set
	 */
	if (!(ntohs(icmphdr->un.echo.sequence) & 1))
		return false;
	/* Clear status bits in reply message */
	icmphdr->un.echo.sequence &= htons(0xFF00);
	if (icmphdr->type == ICMP_EXT_ECHO)
		icmphdr->type = ICMP_EXT_ECHOREPLY;
	else
		icmphdr->type = ICMPV6_EXT_ECHO_REPLY;

/* 학습 해설
 * ICMP Probe 상태 비트: 인터페이스 Up과 주소 존재는 서로 다르다
 * 인터페이스가 켜져 있다는 사실과 IPv4·IPv6 주소가 있다는 사실은 독립적입니다. 세 상태를 하나의 성공 여부로 압축하면 어떤 구성이 되어 있는지 알 수 없어 응답은 각각의 비트를 사용합니다.
 * 식별자에 맞는 장치를 찾지 못하면 NO_IF code와 true를 반환합니다. 찾으면 IFF_UP일 때 ACTIVE,IPv4 in_device와 ifa_list가 있으면 IPV4,IPv6 inet6_dev와 비어 있지 않은 addr_list가 있으면 IPV6를 설정합니다. 장치 참조를 dev_put으로 놓고 status를 htons하여 sequence에 OR합니다.
 * 장치가 UP이지만 주소 목록이 모두 비어 있으면 ACTIVE만 켜집니다. 장치가 DOWN이어도 주소 목록이 남아 있으면 주소 비트는 켜질 수 있습니다. 원래 sequence=0xAB01이면 초기 마스킹 뒤0xAB00이 되고 하위 바이트에 상태를 넣습니다. 상위 바이트는 남지만 원래 하위 비트를 그대로 보존하는 방식이 아닙니다.
 */
bool icmp_build_probe(struct sk_buff *skb, struct icmphdr *icmphdr)
{
	struct icmp_ext_hdr *ext_hdr, _ext_hdr;
	struct icmp_ext_echo_iio *iio, _iio;
	struct net *net = dev_net(skb->dev);
	struct inet6_dev *in6_dev;
	struct in_device *in_dev;
	struct net_device *dev;
	char buff[IFNAMSIZ];
	u16 ident_len;
	u8 status;

	if (!READ_ONCE(net->ipv4.sysctl_icmp_echo_enable_probe))
		return false;

	/* We currently only support probing interfaces on the proxy node
	 * Check to ensure L-bit is set
	 */
	if (!(ntohs(icmphdr->un.echo.sequence) & 1))
		return false;
	/* Clear status bits in reply message */
	icmphdr->un.echo.sequence &= htons(0xFF00);
	if (icmphdr->type == ICMP_EXT_ECHO)
		icmphdr->type = ICMP_EXT_ECHOREPLY;
	else
		icmphdr->type = ICMPV6_EXT_ECHO_REPLY;

/* 학습 해설
 * ICMP RFC4884 확장: 인용 길이를 Payload Offset으로 바꾸고 경계 검사
 * 확장 오류 메시지에는 원본 패킷 인용 뒤 추가 객체들이 붙습니다. 커널이 앞 헤더를 제거한 skb에서 원래 기준의 offset을 그대로 쓰면 엉뚱한 바이트를 객체 헤더로 읽게 되어 기준점 변환이 필요합니다.
 * ip_icmp_error_rfc4884는 hlen=-skb_transport_offset-thlen으로 제거된 헤더 길이를 계산합니다. 입력 off가128보다 작거나 hlen보다 작으면 종료합니다. off에서 hlen을 뺀 뒤 확장 헤더가 skb 안에 들어가는지 검사하고 out->len에 payload 기준 offset을 저장합니다. validate 실패 시 INVALID flag를 OR합니다.
 * 입력 off=128,hlen=28이면 출력 offset은100입니다. validate는 확장 헤더를 읽지 못하면 false,version이2가 아니면 true입니다. version2에서 checksum이0이 아니면 실제 checksum을 검증합니다. 각 객체 길이는 객체 헤더 이상이어야 하고 off+olen이 skb->len을 넘으면 false입니다. 길이0을 허용하지 않아 순회가 같은 자리에서 무한 반복하는 것을 피합니다.
 */
void ip_icmp_error_rfc4884(const struct sk_buff *skb,
			   struct sock_ee_data_rfc4884 *out,
			   int thlen, int off)
{
	int hlen;

	/* original datagram headers: end of icmph to payload (skb->data) */
	hlen = -skb_transport_offset(skb) - thlen;

	/* per rfc 4884: minimal datagram length of 128 bytes */
	if (off < 128 || off < hlen)
		return;

	/* kernel has stripped headers: return payload offset in bytes */
	off -= hlen;
	if (off + sizeof(struct icmp_ext_hdr) > skb->len)
		return;

	out->len = off;

	if (!ip_icmp_error_rfc4884_validate(skb, off))
		out->flags |= SO_EE_RFC4884_FLAG_INVALID;
}
EXPORT_SYMBOL_GPL(ip_icmp_error_rfc4884);

