 */
static struct rtable *icmp_route_lookup(struct net *net,
					struct flowi4 *fl4,
					struct sk_buff *skb_in,
					const struct iphdr *iph,
					__be32 saddr, u8 tos, u32 mark,
					int type, int code,
					struct icmp_bxm *param)
{
	struct net_device *route_lookup_dev;
	struct dst_entry *dst, *dst2;
	struct rtable *rt, *rt2;
	struct flowi4 fl4_dec;
	int err;

	memset(fl4, 0, sizeof(*fl4));
	fl4->daddr = (param->replyopts.opt.opt.srr ?
		      param->replyopts.opt.opt.faddr : iph->saddr);
	fl4->saddr = saddr;
	fl4->flowi4_mark = mark;
	fl4->flowi4_uid = sock_net_uid(net, NULL);
	fl4->flowi4_tos = tos & INET_DSCP_MASK;
	fl4->flowi4_proto = IPPROTO_ICMP;
	fl4->fl4_icmp_type = type;
	fl4->fl4_icmp_code = code;
	route_lookup_dev = icmp_get_route_lookup_dev(skb_in);
	fl4->flowi4_oif = l3mdev_master_ifindex(route_lookup_dev);

/* 학습 해설
 * ICMP NAT 인용 복구: 주소를 잠시 바꿨다가 반드시 되돌리기
 * 송신 장치에서 오류를 만들 때 패킷의 출발지 주소가 이미 NAT로 바뀌었을 수 있습니다. 오류에 포함할 원본 관점을 맞추려면 conntrack의 원래 주소를 사용하되 다른 사용자가 보는 skb를 함부로 영구 변경하지 않아야 합니다.
 * CONFIG_NF_NAT의 icmp_ndo_send는 conntrack이 없거나 SRC_NAT 상태가 아니면 바로 __icmp_send를 호출합니다. NAT 대상 skb가 공유되면 GFP_ATOMIC으로 clone합니다. skb 존재·네트워크 헤더 범위·헤더까지 writable 확보를 검사하고 실패하면 정리합니다. 원래 saddr를 저장하고 conntrack 원래 방향 tuple의 출발지로 바꿔 __icmp_send를 호출한 뒤 저장값으로 복원합니다.
 * NAT 후 출발지 B가 담긴 skb에서 원래 주소 A를 잠시 사용해 ICMP 오류를 구성하고,함수 종료 전 다시 B로 돌립니다. clone은 모든 패킷 데이터를 무조건 깊게 복사한다는 뜻이 아니므로 skb_ensure_writable 검사도 필요합니다. 원본이 공유되지 않았다면 원본 skb를 잠시 변경하되 주소 복원은 동일하게 수행합니다.
 */
void icmp_ndo_send(struct sk_buff *skb_in, int type, int code, __be32 info)
{
	struct sk_buff *cloned_skb = NULL;
	struct ip_options opts = { 0 };
	enum ip_conntrack_info ctinfo;
	struct nf_conn *ct;
	__be32 orig_ip;

	ct = nf_ct_get(skb_in, &ctinfo);
	if (!ct || !(ct->status & IPS_SRC_NAT)) {
		__icmp_send(skb_in, type, code, info, &opts);
		return;
	}

	if (skb_shared(skb_in))
		skb_in = cloned_skb = skb_clone(skb_in, GFP_ATOMIC);

	if (unlikely(!skb_in || skb_network_header(skb_in) < skb_in->head ||
	    (skb_network_header(skb_in) + sizeof(struct iphdr)) >
	    skb_tail_pointer(skb_in) || skb_ensure_writable(skb_in,
	    skb_network_offset(skb_in) + sizeof(struct iphdr))))
		goto out;

	orig_ip = ip_hdr(skb_in)->saddr;
	ip_hdr(skb_in)->saddr = ct->tuplehash[0].tuple.src.u3.ip;
	__icmp_send(skb_in, type, code, info, &opts);

/* 학습 해설
 * KVM IRQFD 알림: Eventfd 숫자가 곧 같은 수의 인터럽트는 아니다
 * 사용자 공간 장치 모델이 eventfd를 울리면 KVM이 가상 머신에 인터럽트를 전달할 수 있습니다. 그러나 eventfd 카운터는 알림을 모으는 수단이며 그 숫자만큼 항상 독립 인터럽트를 반복 주입하는 구현은 아닙니다.
 * irqfd_wakeup은 wait queue 잠금과 인터럽트 비활성 문맥에서 호출됩니다. EPOLLIN이면 eventfd_ctx_do_read로 cnt를 읽고 irq_srcu 읽기 구간에서 seqcount로 irq_entry를 일관되게 복사합니다. arch의 inatomic 주입이 EWOULDBLOCK일 때만 inject work를 예약합니다. EPOLLIN 처리 결과는 ret1입니다. EPOLLHUP도 있으면 irqfds.lock 아래 활성 여부를 확인해 비활성화합니다.
 * cnt가3이어도 코드에는3회 반복 주입 루프가 없습니다. work 예약도 이미 pending인 작업과 합쳐질 수 있으므로 카운터 증가와 guest 인터럽트 관측 횟수를 일대일로 가정하면 안 됩니다. arch helper가 EWOULDBLOCK 이외의 오류를 돌려줘도 이 callback에는 모든 오류를 동일하게 work로 재시도하는 분기가 없습니다.
 */
irqfd_wakeup(wait_queue_entry_t *wait, unsigned mode, int sync, void *key)
{
	struct kvm_kernel_irqfd *irqfd =
		container_of(wait, struct kvm_kernel_irqfd, wait);
	__poll_t flags = key_to_poll(key);
	struct kvm_kernel_irq_routing_entry irq;
	struct kvm *kvm = irqfd->kvm;
	unsigned seq;
	int idx;
	int ret = 0;

	if (flags & EPOLLIN) {
		u64 cnt;
		eventfd_ctx_do_read(irqfd->eventfd, &cnt);

		idx = srcu_read_lock(&kvm->irq_srcu);
		do {
			seq = read_seqcount_begin(&irqfd->irq_entry_sc);
			irq = irqfd->irq_entry;
		} while (read_seqcount_retry(&irqfd->irq_entry_sc, seq));
		/* An event has been signaled, inject an interrupt */
		if (kvm_arch_set_irq_inatomic(&irq, kvm,
					      KVM_USERSPACE_IRQ_SOURCE_ID, 1,
					      false) == -EWOULDBLOCK)
			schedule_work(&irqfd->inject);
		srcu_read_unlock(&kvm->irq_srcu, idx);

/* 학습 해설
 * KVM IRQFD Route Snapshot: Seqcount와 SRCU는 서로 다른 문제를 푼다
 * IRQ route를 갱신하는 동안 callback이 구조체의 일부는 옛 값,일부는 새 값으로 읽으면 잘못된 전달 대상이 만들어질 수 있습니다. 일관된 값 복사와 참조하는 경로의 수명 보호는 다른 문제라 두 장치가 함께 쓰입니다.
 * irqfd_update는 irqfds.lock 아래 GSI를 route 항목들로 변환합니다. seqcount 쓰기 구간에서 결과가 정확히1개이면 전체 entry를 복사하고 그렇지 않으면 type0을 설정합니다. reader는 read_seqcount_begin,구조체 복사,retry를 반복합니다. callback은 이 읽기와 inatomic 호출을 irq_srcu 읽기 구간으로 감쌉니다.
 * route 항목이2개라고 첫 번째만 골라 빠른 주입을 하는 것은 아닙니다. type0으로 단일 route 빠른 경로를 표현하지 않도록 합니다. writer가 reader의 복사 도중 진입하면 retry가 true여서 다시 복사합니다. SRCU만 잡는다고 여러 필드의 snapshot이 자동으로 원자적이 되는 것은 아닙니다.
 */
static void irqfd_update(struct kvm *kvm, struct kvm_kernel_irqfd *irqfd)
{
	struct kvm_kernel_irq_routing_entry *e;
	struct kvm_kernel_irq_routing_entry entries[KVM_NR_IRQCHIPS];
	int n_entries;

	n_entries = kvm_irq_map_gsi(kvm, entries, irqfd->gsi);

	write_seqcount_begin(&irqfd->irq_entry_sc);

	e = entries;
	if (n_entries == 1)
		irqfd->irq_entry = *e;
	else
		irqfd->irq_entry.type = 0;

	write_seqcount_end(&irqfd->irq_entry_sc);
}

