 * A와 B가 같은 GSI를 공유하고 ACK 뒤 A에 알린 다음 A가 다시 level을 올렸다고 가정합니다. B에 알리기 직전에 또 level0을 쓰면 A의 새 요청을 지울 수 있습니다. 그래서 먼저 한 번 내리고 A와 B 모두에게 알리는 순서를 사용합니다. resamplefd 알림과 guest IRQ assert는 반대 방향의 사건입니다.
 */
irqfd_resampler_ack(struct kvm_irq_ack_notifier *kian)
{
	struct kvm_kernel_irqfd_resampler *resampler;
	struct kvm *kvm;
	int idx;

	resampler = container_of(kian,
			struct kvm_kernel_irqfd_resampler, notifier);
	kvm = resampler->kvm;

	kvm_set_irq(kvm, KVM_IRQFD_RESAMPLE_IRQ_SOURCE_ID,
		    resampler->notifier.gsi, 0, false);

	idx = srcu_read_lock(&kvm->irq_srcu);
	irqfd_resampler_notify(resampler);
	srcu_read_unlock(&kvm->irq_srcu, idx);
}

static void
irqfd_resampler_shutdown(struct kvm_kernel_irqfd *irqfd)
{
	struct kvm_kernel_irqfd_resampler *resampler = irqfd->resampler;
	struct kvm *kvm = resampler->kvm;

	mutex_lock(&kvm->irqfds.resampler_lock);

/* 학습 해설
 * KVM IRQFD 등록: 기존 Eventfd 알림을 놓치지 않는 Publish와 Poll
 * 알림을 연결하는 동안 이미 eventfd가 준비 상태가 되면 등록 후 새 신호만 기다려서는 기존 사건을 놓칠 수 있습니다. 반대로 객체 초기화가 끝나기 전에 파일 참조를 놓으면 HUP 정리가 미완성 객체와 경쟁할 수 있습니다.
