static void cpudl_heapify_down(struct cpudl *cp, int idx)
{
	int l, r, largest;

	int orig_cpu = cp->elements[idx].cpu;
	u64 orig_dl = cp->elements[idx].dl;

	if (left_child(idx) >= cp->size)
		return;

	/* adapted from lib/prio_heap.c */
	while (1) {
		u64 largest_dl;

		l = left_child(idx);
		r = right_child(idx);
		largest = idx;
		largest_dl = orig_dl;

		if ((l < cp->size) && dl_time_before(orig_dl,
						cp->elements[l].dl)) {
			largest = l;
			largest_dl = cp->elements[l].dl;
		}
		if ((r < cp->size) && dl_time_before(largest_dl,
						cp->elements[r].dl))

/* 학습 해설
 * CPU Deadline Set·Clear: 마지막 항목으로 빈자리를 메우기
 * CPU 하나의 deadline 갱신이나 삭제 때문에 배열 전체를 밀면 CPU가 많을수록 비용이 커집니다. 역색인과 마지막 항목 교체를 사용하면 연속된 heap 배열을 유지하면서 한 경로만 복구할 수 있습니다.
 * set은 해당 rq 잠금 보유를 전제로 cpudl raw spinlock을 irqsave로 잡습니다. idx가 INVALID면 끝에 추가하고 역색인·heapify_up·free bit 해제를 수행합니다. 이미 있으면 dl을 갱신하고 heapify합니다. clear는 대상 위치에 마지막 cpu·dl을 복사하고 size를 줄인 뒤 새 CPU의 idx와 제거 CPU의 INVALID를 기록하고 heapify,free bit 설정을 합니다.
 * [100,90,70,60]에서 root CPU를 제거하면 마지막60을 root로 옮긴 뒤90을 올려 [90,60,70]이 됩니다. size가3이므로 옛 네 번째 칸은 유효 heap 밖입니다. 제거된 칸 전체를0으로 덮는 것이 삭제의 정의가 아닙니다. CPU 번호로 된 역색인은 heap 유효 범위와 다른 기준이므로 유효 idx 갱신이 핵심입니다.
 */
void cpudl_clear(struct cpudl *cp, int cpu)
{
	int old_idx, new_cpu;
	unsigned long flags;

	WARN_ON(!cpu_present(cpu));

	raw_spin_lock_irqsave(&cp->lock, flags);

	old_idx = cp->elements[cpu].idx;
	if (old_idx == IDX_INVALID) {
		/*
		 * Nothing to remove if old_idx was invalid.
		 * This could happen if a rq_offline_dl is
		 * called for a CPU without -dl tasks running.
		 */
	} else {
		new_cpu = cp->elements[cp->size - 1].cpu;
		cp->elements[old_idx].dl = cp->elements[cp->size - 1].dl;
		cp->elements[old_idx].cpu = new_cpu;
		cp->size--;
		cp->elements[new_cpu].idx = old_idx;
		cp->elements[cpu].idx = IDX_INVALID;
		cpudl_heapify(cp, old_idx);

		cpumask_set_cpu(cpu, cp->free_cpus);

