/* 학습 해설
 * Autogroup 적용 조건: 명시적 Task Group과 종료 중 태스크를 구분하기
 * 자동으로 묶은 작업 그룹이 명시적으로 관리하는 그룹 정책을 덮어쓰면 관리자가 의도한 CPU 배분이 달라질 수 있습니다. 종료 중인 태스크도 일반 이동 목록에서 빠질 수 있어 자동 그룹을 계속 참조할 수 있는지 별도로 판단해야 합니다.
 * task_wants_autogroup은 현재 task group이 root_task_group이 아니면 false,PF_EXITING이면 false,그 외에는 true입니다. autogroup.h의 선택 helper는 enabled를 READ_ONCE로 읽고 이 조건까지 만족할 때 signal->autogroup->tg를 사용합니다. 아니면 원래 tg를 그대로 반환합니다. CONFIG_SCHED_AUTOGROUP이 없으면 선택 stub도 원래 tg를 반환합니다.
 * 태스크가 명시적 비root CPU group에 속하면 enabled=1이어도 이 helper는 자동 그룹으로 바꾸지 않습니다. root 소속 정상 태스크는 적용 후보이고,종료 flag가 설정되면 적용 대상에서 빠집니다. enabled 변수 하나만 켜져 있다고 모든 태스크가 같은 자동 그룹으로 강제 이동하는 구조가 아닙니다.
 */
bool task_wants_autogroup(struct task_struct *p, struct task_group *tg)
{
	if (tg != &root_task_group)
		return false;
	/*
	 * If we race with autogroup_move_group() the caller can use the old
	 * value of signal->autogroup but in this case sched_move_task() will
	 * be called again before autogroup_kref_put().
	 *
	 * However, there is no way sched_autogroup_exit_task() could tell us
	 * to avoid autogroup->tg, so we abuse PF_EXITING flag for this case.
	 */
	if (p->flags & PF_EXITING)
		return false;

	return true;
}

void sched_autogroup_exit_task(struct task_struct *p)
{
	/*
	 * We are going to call exit_notify() and autogroup_move_group() can't
	 * see this thread after that: we can no longer use signal->autogroup.
	 * See the PF_EXITING check in task_wants_autogroup().
	 */
	sched_move_task(p);

/* 학습 해설
 * Autogroup 생성 실패의 대안: 기본 그룹 참조와 RT 구조 재사용
 * 새 자동 그룹을 만들 메모리가 부족하다고 태스크가 그룹 없이 남아서는 안 됩니다. 사용할 수 있는 기본 그룹으로 돌아가면서도 호출자에게 전달하는 참조 소유권은 성공 경로와 맞춰야 합니다.
 * create는 autogroup을 kzalloc하고 root 밑 task group을 생성합니다. 성공하면 kref·rwsem·증가 ID·tg 연결을 설정하고 tg->autogroup을 연결한 뒤 online합니다. 실패하면 필요한 임시 메모리를 정리하고 제한된 경고를 출력한 후 기본 autogroup의 참조를 하나 얻어 반환합니다. NULL이나 오류 포인터를 반환하는 함수로 설명하면 안 됩니다.
 * 호출자는 새 객체를 받았든 기본 객체를 받았든 임시 참조를 하나 소유합니다. create_attach는 move_group을 호출한 뒤 이 임시 참조를 put합니다. CONFIG_RT_GROUP_SCHED이면 새 tg의 RT 구조를 먼저 해제하고 root의 rt_se·rt_rq를 가리키게 합니다. 모든 자동 그룹에 별도 RT 대역폭 구조를 그대로 유지하는 방식이 아닙니다.
 */
static inline struct autogroup *autogroup_create(void)
{
	struct autogroup *ag = kzalloc(sizeof(*ag), GFP_KERNEL);
	struct task_group *tg;

	if (!ag)
		goto out_fail;

	tg = sched_create_group(&root_task_group);
	if (IS_ERR(tg))
		goto out_free;

	kref_init(&ag->kref);
	init_rwsem(&ag->lock);
	ag->id = atomic_inc_return(&autogroup_seq_nr);
	ag->tg = tg;
#ifdef CONFIG_RT_GROUP_SCHED
	/*
	 * Autogroup RT tasks are redirected to the root task group
	 * so we don't have to move tasks around upon policy change,
	 * or flail around trying to allocate bandwidth on the fly.
	 * A bandwidth exception in __sched_setscheduler() allows
	 * the policy change to proceed.
	 */
	free_rt_sched_group(tg);
	tg->rt_se = root_task_group.rt_se;

/* 학습 해설
 * Autogroup 이동과 Fork: Signal 포인터를 바꾼 뒤 모든 스레드를 옮기기
 * 스레드들은 signal 구조체의 autogroup을 공유하지만 스케줄러 내부 상태는 태스크별로 존재합니다. 포인터만 바꾸고 옛 그룹을 해제하면 실제 실행 상태가 아직 옛 그룹을 참조할 수 있어 모든 스레드의 스케줄러 이동을 마친 뒤 참조를 놓아야 합니다.
 * move_group은 sighand 잠금을 얻고 기존 그룹과 새 그룹이 같으면 그대로 종료합니다. 다르면 새 그룹 참조를 얻어 signal->autogroup을 바꾸고 for_each_thread에서 sched_move_task를 호출합니다. 잠금을 푼 뒤 옛 그룹 참조를 put합니다. 잠금 획득 실패는 WARN 후 반환합니다. detach는 이 함수를 기본 그룹과 함께 호출하며 siglock 아래에서 호출할 수 없습니다.
 * 그룹 A에서 B로 옮길 때 먼저 B 참조를 확보하고 포인터를 B로 바꿉니다. 그 뒤 스레드 T1·T2의 스케줄러 상태를 갱신하고 마지막에 A를 놓습니다. A를 먼저 put하면 이동 전 상태가 사라진 그룹을 사용할 수 있습니다. 이미 스레드 목록에서 빠진 종료 태스크는 sched_autogroup_exit_task의 sched_move_task와 PF_EXITING 조건으로 처리합니다.
 */
autogroup_move_group(struct task_struct *p, struct autogroup *ag)
{
	struct autogroup *prev;
	struct task_struct *t;
	unsigned long flags;

	if (WARN_ON_ONCE(!lock_task_sighand(p, &flags)))
		return;

	prev = p->signal->autogroup;
	if (prev == ag) {
		unlock_task_sighand(p, &flags);
		return;
	}

	p->signal->autogroup = autogroup_kref_get(ag);
	/*
	 * We can't avoid sched_move_task() after we changed signal->autogroup,
	 * this process can already run with task_group() == prev->tg or we can
	 * race with cgroup code which can read autogroup = prev under rq->lock.
	 * In the latter case for_each_thread() can not miss a migrating thread,
	 * cpu_cgroup_attach() must not be possible after cgroup_exit() and it
	 * can't be removed from thread list, we hold ->siglock.
	 *
	 * If an exiting thread was already removed from thread list we rely on
	 * sched_autogroup_exit_task().
	 */

/* 학습 해설
 * Autogroup Nice와 Shares: 권한 검사 뒤 가중치 표로 변환하기
 * nice 숫자는 CPU 시간을 직접 밀리초로 지정하는 값이 아닙니다. 자동 그룹의 상대적 가중치로 변환해 스케줄러에 적용해야 하며,음수 nice로 더 유리한 배분을 요구할 때는 권한 조건도 필요합니다.
