	if (!capable(CAP_SYS_ADMIN) && time_before(jiffies, next))
		return -EAGAIN;

	next = HZ / 10 + jiffies;
	ag = autogroup_task_get(p);

	idx = array_index_nospec(nice + 20, 40);
	shares = scale_load(sched_prio_to_weight[idx]);

/* 학습 해설
 * Autogroup 조회와 Shares 적용: 표시값은 실제 갱신 성공 뒤 바뀐다
 * 사용자에게 보이는 그룹 nice와 내부 shares가 서로 어긋나면 설정 결과를 해석하기 어렵습니다. 조회와 설정을 같은 그룹 잠금으로 보호하고 실제 적용 실패 시 표시값을 유지해야 합니다.
 * show_task는 그룹 참조를 얻고 tg->autogroup이 없는 경우 출력 없이 정리합니다. 자동 그룹이면 rwsem 읽기 잠금 아래 /autogroup-ID nice N 형식을 출력하고 잠금과 참조를 놓습니다. autogroup_path도 자동 그룹이 아니면0이며,맞으면 snprintf로 이름을 기록하고 그 반환값을 반환합니다. PROC_FS가 없으면 proc 설정·조회 함수들은 포함되지 않습니다.
 * shares 갱신 helper는 root의 sched_entity가 없으면 EINVAL이고 idle 그룹도 거절할 수 있습니다. 허용한 shares는 MIN_SHARES..MAX_SHARES 범위로 clamp하고,바뀌면 각 possible CPU rq 잠금 아래 load와 그룹 기여를 갱신합니다. 그래서 set_nice가 전역 잠금을 잡는 무거운 작업이라고 설명하며 호출 빈도를 제한합니다.
 */
void proc_sched_autogroup_show_task(struct task_struct *p, struct seq_file *m)
{
	struct autogroup *ag = autogroup_task_get(p);

	if (!task_group_is_autogroup(ag->tg))
		goto out;

	down_read(&ag->lock);
	seq_printf(m, "/autogroup-%ld nice %d\n", ag->id, ag->nice);
	up_read(&ag->lock);

out:
	autogroup_kref_put(ag);
}
#endif /* CONFIG_PROC_FS */

int autogroup_path(struct task_group *tg, char *buf, int buflen)
{
	if (!task_group_is_autogroup(tg))
		return 0;

	return snprintf(buf, buflen, "%s-%ld", "/autogroup", tg->autogroup->id);
}

/* 학습 해설
 * PM QoS 집계: 여러 지연 시간 요청에서 왜 최솟값을 고르나
 * 서로 다른 사용자가 허용하는 지연 시간이 다르면 평균값으로는 가장 엄격한 사용자를 만족시킬 수 없습니다. 요구를 동시에 충족하려면 제한의 방향에 맞게 가장 엄격한 값을 골라야 합니다.
 * pm_qos_get_value는 요청 plist가 비면 no_constraint_value를 반환합니다. PM_QOS_MIN이면 정렬 목록 첫 노드의 prio,MAX이면 마지막 prio를 반환합니다. 알 수 없는 type은 경고하고 DEFAULT_VALUE입니다. update_target은 DEFAULT_VALUE 입력을 해당 constraints의 default_value로 치환하고,global spinlock 아래 요청 추가·수정·삭제와 유효 값 갱신을 수행합니다.
 * CPU 지연 요구가100·50·200마이크로초이면 유효 상한은50입니다. 평균116.7이면50을 요구한 사용자를 만족시키지 못합니다.100을80으로 바꿔도 유효 값은50이므로 update_target 반환은0입니다.0이 요청 갱신 실패라는 뜻은 아닙니다.50을 제거하면 남은80·200의 유효 값은80으로 바뀌어1입니다.
 */
static int pm_qos_get_value(struct pm_qos_constraints *c)
{
	if (plist_head_empty(&c->list))
		return c->no_constraint_value;

	switch (c->type) {
	case PM_QOS_MIN:
		return plist_first(&c->list)->prio;

	case PM_QOS_MAX:
		return plist_last(&c->list)->prio;

	default:
		WARN(1, "Unknown PM QoS type in %s\n", __func__);
		return PM_QOS_DEFAULT_VALUE;
	}
}

static void pm_qos_set_value(struct pm_qos_constraints *c, s32 value)
{
	WRITE_ONCE(c->target_value, value);
}

/**
 * pm_qos_update_target - Update a list of PM QoS constraint requests.
 * @c: List of PM QoS requests.
 * @node: Target list entry.
 * @action: Action to carry out (add, update or remove).
 * @value: New request value for the target list entry.
 *
 * Update the given list of PM QoS constraint requests, @c, by carrying an
 * @action involving the @node list entry and @value on it.
 *
 * The recognized values of @action are PM_QOS_ADD_REQ (store @value in @node
 * and add it to the list), PM_QOS_UPDATE_REQ (remove @node from the list, store
 * @value in it and add it to the list again), and PM_QOS_REMOVE_REQ (remove
 * @node from the list, ignore @value).
 *
 * Return: 1 if the aggregate constraint value has changed, 0  otherwise.
 */

/* 학습 해설
 * PM QoS 변경 알림: Spinlock을 놓은 뒤 Callback을 호출하기
 * 요청 목록을 보호하는 잠금을 잡은 채 무거운 callback을 호출하면 잠금 점유가 길어지고 잠들 수 있는 동작과 충돌할 수 있습니다. 목록 변경과 변경 통지를 분리하되 통지가 어떤 시점의 값을 나타내는지 이해해야 합니다.
 * update_target은 irqsave spinlock 아래 이전 집계를 읽고 목록을 갱신한 뒤 새 집계를 target_value에 WRITE_ONCE합니다. 잠금을 복구해 놓고 trace를 기록합니다. 값이 같으면0,달라졌고 notifier가 있으면 blocking_notifier_call_chain에 새 값을 전달한 뒤1입니다. notifier 반환을 이 함수의 오류로 바꾸거나 목록을 되돌리는 처리는 없습니다.
 * A가 값을50으로 갱신하고 잠금을 놓은 직후 B가30으로 갱신할 수 있습니다. A의 callback 인자는 자신이 계산한50이지만 callback에서 다시 read_value를 하면30을 볼 수 있습니다. 따라서 알림 인자와 동시점의 조회값이 항상 같거나 callback 순서가 모든 갱신 순서와 정확히 같다고 보장하면 안 됩니다.
 */
int pm_qos_update_target(struct pm_qos_constraints *c, struct plist_node *node,
			 enum pm_qos_req_action action, int value)
{
	int prev_value, curr_value, new_value;
	unsigned long flags;

	spin_lock_irqsave(&pm_qos_lock, flags);

	prev_value = pm_qos_get_value(c);
	if (value == PM_QOS_DEFAULT_VALUE)
		new_value = c->default_value;
	else
		new_value = value;

	switch (action) {
	case PM_QOS_REMOVE_REQ:
		plist_del(node, &c->list);
		break;
	case PM_QOS_UPDATE_REQ:
		/*
		 * To change the list, atomically remove, reinit with new value
		 * and add, then see if the aggregate has changed.
		 */
		plist_del(node, &c->list);
		fallthrough;
	case PM_QOS_ADD_REQ:

/* 학습 해설
 * PM QoS Flags 삭제: OR 결과에서 단순히 비트를 빼면 안 되는 이유
 * 여러 요청이 같은 전원 정책 비트를 요구할 수 있습니다. 요청 하나를 지울 때 그 요청의 비트를 집계 결과에서 모두 지우면 다른 요청이 여전히 요구하는 비트까지 사라집니다.
 * flags 집계는 모든 요청 flags의 bitwise OR입니다. remove는 요청을 list_del한 뒤 남은 목록을 처음부터 순회해 val0에 OR하고 effective_flags를 갱신합니다. UPDATE는 제거·재집계 후 새 flags를 가진 요청을 다시 추가하고 OR합니다. ADD는 목록 끝에 넣고 OR합니다. 전체 과정은 global irqsave spinlock 아래이며 이전·이후 집계가 다른지를 bool로 반환합니다.
 * A=0011,B=0001이면 전체는0011입니다. A를 제거한 뒤 정답은 B의0001입니다. 기존0011에서 A의 비트를 AND NOT 하면0000이 되어 B의 요구를 잃습니다. 따라서 OR는 추가는 쉽지만 삭제는 소유자가 몇 명 남았는지 알아야 하며 이 구현은 남은 목록 재계산으로 해결합니다.
 */
static void pm_qos_flags_remove_req(struct pm_qos_flags *pqf,
				    struct pm_qos_flags_request *req)
{
	s32 val = 0;

	list_del(&req->node);
	list_for_each_entry(req, &pqf->list, node)
		val |= req->flags;

	pqf->effective_flags = val;
}

/**
 * pm_qos_update_flags - Update a set of PM QoS flags.
 * @pqf: Set of PM QoS flags to update.
 * @req: Request to add to the set, to modify, or to remove from the set.
 * @action: Action to take on the set.
 * @val: Value of the request to add or modify.
 *
 * Return: 1 if the aggregate constraint value has changed, 0 otherwise.
 */
bool pm_qos_update_flags(struct pm_qos_flags *pqf,
			 struct pm_qos_flags_request *req,
			 enum pm_qos_req_action action, s32 val)
{
	unsigned long irqflags;

/* 학습 해설
 * CPU Latency QoS 요청 수명: 핸들을 유지하고 유효 값이 바뀔 때 깨우기
 * 전원 관리 요구가 존재하는 동안 어떤 요청을 갱신하거나 제거할지 식별할 객체가 필요합니다. 요청 객체를 먼저 없애면 목록이 사라진 메모리를 가리킬 수 있어 등록 수명과 메모리 수명을 맞춰야 합니다.
 * CPU latency 제약은 MIN이고 기본·빈 값은 PM_QOS_CPU_LATENCY_DEFAULT_VALUE입니다. add는 NULL이나 기본 sentinel 이외 음수이면 조용히 반환하고,이미 active이면 경고합니다. req->qos를 전역 constraints로 설정한 뒤 추가합니다. active는 이 포인터가 전역 constraints와 같은지 검사합니다. apply는 집계가 바뀐 경우에만 wake_up_all_idle_cpus를 호출합니다.
 * 요청 A=50이 있을 때 B=100을 추가하면 유효 값은50 그대로라 이 apply에서 idle CPU를 깨우지 않습니다. A를 제거해100으로 완화될 때도 값이 바뀌므로 깨웁니다. 강화될 때만 깨운다고 설명하면 안 됩니다. 이 요청이 wake-up을 요구한다고 CPU 실행 지연이 반드시 해당 숫자 이하로 보장된다고 확대하지 않습니다.
 */
void cpu_latency_qos_add_request(struct pm_qos_request *req, s32 value)
{
	if (!req || cpu_latency_qos_value_invalid(value))
		return;

	if (cpu_latency_qos_request_active(req)) {
		WARN(1, KERN_ERR "%s called for already added request\n", __func__);
		return;
	}

	trace_pm_qos_add_request(value);

	req->qos = &cpu_latency_constraints;
	cpu_latency_qos_apply(req, PM_QOS_ADD_REQ, value);
}
EXPORT_SYMBOL_GPL(cpu_latency_qos_add_request);

/**
 * cpu_latency_qos_update_request - Modify existing CPU latency QoS request.
 * @req : QoS request to update.
 * @new_value: New requested constraint value.
 *
 * Use @new_value to update the QoS request represented by @req in the CPU
 * latency QoS list along with updating the effective constraint value for that
 * list.
 */

/* 학습 해설
 * CPU DMA Latency 파일: 읽기는 내 요청이 아니라 전체 집계값
 * 여러 프로세스가 각자 지연 요구를 등록해도 실제 전원 정책에 적용할 값은 전체 집계입니다. 파일 하나의 private 요청과 시스템 전체 결과를 구별해야 읽은 값이 내가 쓴 값과 다를 때 원인을 알 수 있습니다.
 * open은 req를 kzalloc해 기본 요청을 추가하고 private_data에 저장합니다. release는 private_data를NULL로 만들고 요청 제거 후 kfree합니다. read는 요청이 active인지 검사하고 spinlock 아래 전역 집계를 읽어 simple_read_from_buffer로 s32 크기의 바이너리 값을 전달합니다. f_pos를 사용하므로 위치와 count에 따라 일부 바이트 또는 EOF를 반환할 수 있습니다.
 * 파일 A로100,파일 B로50을 요청하면 A를 읽어도 전체 값50을 얻습니다. B의 마지막 파일 참조가 해제되어 요청이 제거되면 값은100이 됩니다. 파일 요청은 open file 객체 수명에 연결되므로 dup된 FD 하나만 닫았다고 release가 즉시 실행된다고 단정하지 않습니다.
 */
static ssize_t cpu_latency_qos_read(struct file *filp, char __user *buf,
				    size_t count, loff_t *f_pos)
{
	struct pm_qos_request *req = filp->private_data;
	unsigned long flags;
	s32 value;

	if (!req || !cpu_latency_qos_request_active(req))
		return -EINVAL;

	spin_lock_irqsave(&pm_qos_lock, flags);
	value = pm_qos_get_value(&cpu_latency_constraints);
	spin_unlock_irqrestore(&pm_qos_lock, flags);

	return simple_read_from_buffer(buf, count, f_pos, &value, sizeof(s32));
}

static ssize_t cpu_latency_qos_write(struct file *filp, const char __user *buf,
				     size_t count, loff_t *f_pos)
{
	s32 value;

	if (count == sizeof(s32)) {
		if (copy_from_user(&value, buf, sizeof(s32)))
			return -EFAULT;
	} else {

/* 학습 해설
 * CPU Latency Write 형식: 정확히4바이트면 문자열이 아니다
 * 같은 파일에 바이너리 숫자와 문자열을 허용할 때 어느 형식을 선택하는지 명확히 알아야 합니다. 눈으로 숫자처럼 보이는 입력도 길이 조건 때문에 전혀 다른 값으로 해석될 수 있습니다.
 * count가 sizeof(s32)인4이면 copy_from_user로 숫자의 메모리 표현을 직접 읽습니다. 다른 길이면 kstrtos32_from_user의 base16으로 파싱합니다. 복사 실패는 EFAULT,문자열 파싱 실패는 그 오류입니다. 값을 얻으면 void인 update_request를 호출하고 count를 반환합니다.
 * ASCII "1000" 네 바이트는 십진1000도 hex0x1000도 아닙니다. 이 분기는 바이트31 30 30 30을 정수로 읽으며 little-endian이면0x30303031입니다. 명확한 문자열 예 "0x00000064"는10바이트라 hex 파싱되어100입니다. 바이너리 입력은 호스트 정수 표현과 byte order를 맞춰야 합니다.
 */
static ssize_t cpu_latency_qos_write(struct file *filp, const char __user *buf,
				     size_t count, loff_t *f_pos)
{
	s32 value;

	if (count == sizeof(s32)) {
		if (copy_from_user(&value, buf, sizeof(s32)))
			return -EFAULT;
	} else {
		int ret;

		ret = kstrtos32_from_user(buf, count, 16, &value);
		if (ret)
			return ret;
	}

	cpu_latency_qos_update_request(filp->private_data, value);

	return count;
}

static const struct file_operations cpu_latency_qos_fops = {
	.write = cpu_latency_qos_write,
	.read = cpu_latency_qos_read,
	.open = cpu_latency_qos_open,
	.release = cpu_latency_qos_release,

/* 학습 해설
 * Frequency QoS 최소·최대: 최소 주파수 요청은 왜 MAX로 집계하나
 * 최소 주파수 요구는 적어도 그만큼 빨라야 한다는 뜻이고 최대 주파수 요구는 그보다 빨라서는 안 된다는 뜻입니다. 같은 숫자라도 제약 방향이 반대이므로 집계 연산도 반대입니다.
 * freq_constraints_init은 min_freq를 PM_QOS_MAX,default0으로 초기화하고 max_freq는 PM_QOS_MIN,default S32_MAX로 초기화합니다. 각각 별도 plist와 blocking notifier head를 가집니다. read_value는 type에 맞는 target을 읽고 qos가NULL 또는 오류 포인터이면 해당 기본값을 반환합니다. 알 수 없는 type은 WARN 후0입니다.
 * 같은 단위에서 최소 요구800·1200이면 적어도1200이 필요하므로 MAX입니다. 최대 요구2400·1800이면1800을 넘지 않아야 하므로 MIN입니다. 최소2000과 최대1800처럼 두 집계가 충돌해도 이 초기화·집계 코드는 두 값을 자동으로 하나의 실행 주파수로 조정하지 않습니다. 실제 적용자는 자신의 정책과 장치 한계를 함께 처리해야 합니다.
 */
void freq_constraints_init(struct freq_constraints *qos)
{
	struct pm_qos_constraints *c;

	c = &qos->min_freq;
	plist_head_init(&c->list);
	c->target_value = FREQ_QOS_MIN_DEFAULT_VALUE;
	c->default_value = FREQ_QOS_MIN_DEFAULT_VALUE;
	c->no_constraint_value = FREQ_QOS_MIN_DEFAULT_VALUE;
	c->type = PM_QOS_MAX;
	c->notifiers = &qos->min_freq_notifiers;
	BLOCKING_INIT_NOTIFIER_HEAD(c->notifiers);

	c = &qos->max_freq;
	plist_head_init(&c->list);
	c->target_value = FREQ_QOS_MAX_DEFAULT_VALUE;
	c->default_value = FREQ_QOS_MAX_DEFAULT_VALUE;
	c->no_constraint_value = FREQ_QOS_MAX_DEFAULT_VALUE;
	c->type = PM_QOS_MIN;
	c->notifiers = &qos->max_freq_notifiers;
	BLOCKING_INIT_NOTIFIER_HEAD(c->notifiers);
}

/**
 * freq_qos_read_value - Get frequency QoS constraint for a given list.
 * @qos: Constraints to evaluate.
 * @type: QoS request type.
 */
